intro x₀,
let S := ProbabilityTheory.integrableExpSet X μ,
let U := interior S,
let f := ProbabilityTheory.cgf X μ,
let g := fun t => (X t : ℝ) * t - f t,
have hS : S = {t : ℝ | ∀ ω, exp (t * (X ω)) ∈ L¹ μ} := by rfl,
have hU : U = interior S := by rfl,
let h_open : IsOpen U := by simp [hU],
let h_finite : ∀ t ∈ U, ∃ ε > 0, ∀ t' ∈ ball t ε, t' ∈ U :=
  by { intro t ht, exact (h_open.mem_interior t ht).exists },
let h_cont : ContinuousOn f U :=
  by { intro t ht, exact (ProbabilityTheory.cgf_continuous_at X μ t ht).ContinuousOn },
let h_diff : DifferentiableOn ℝ f U :=
  by { intro t ht, exact (ProbabilityTaylorSeries.differentiable_cgf X μ t ht).DifferentiableOn },
let h_diff_eq : ∀ t ∈ U, HasDerivativeAt (fun t' => (X t' : ℝ) * t' - f t') (X t - f' t) t :=
  by { intro t ht, exact (ProbabilityTaylorSeries.differentiable_cgf X μ t ht).HasDerivativeAt }
